import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';
const R=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url)));
test('October 5 preserves honest delivery and review counts',()=>{const b=R('assets/citizen-work.json'),d=b.deliveries.filter(x=>x.executionId==='daily-20261005-root');assert.equal(d.length,1);assert.equal(d[0].citizenId,'saeon');assert.equal(d[0].review,null);const f=R('assets/research-frontiers.json');for(const id of ['nullroute','sigma','leimma','pharma','runo','vox','cynosure','memoria'])for(const l of ['zh','en','ko'])assert.ok(f.citizens[id][l].some(x=>x.observationId===`2026-10-05-gap-${id}`&&!x.publicationId));});
test('October 5 snapshots retain dates, evidence scope and candidate-only learning',()=>{const e=R('research/2026-10-05/energy-observatory.json');assert.equal(e.updatedAt,'2026-10-05');assert.equal(e.nextUpdate,'2026-10-12');assert.equal(e.sources.find(s=>s.id==='nobel').access,'search_excerpt');assert.equal(e.events.find(x=>x.id==='japan27-autumn').start,'2027-10-06');assert.ok(e.editions.some(x=>x.date==='2026-09-28'));const w=R('assets/weekly-learning.json');assert.equal(w.entries.length,3);assert.ok(w.entries.every(x=>x.publishedAt===null));assert.ok(w.experiments.every(x=>x.status==='candidate'));assert.ok(w.previousExperimentEvaluation.every(x=>x.status==='due_unverified'));assert.equal(R(w.archive).updated,'2026-09-28');});
